def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 2:
                out[r][c] = 4
                for j in range(c + 1, len(row)):
                    if grid[r][j] == 5:
                        break
                    out[r][j] = 2
        if row[0] == 5:
            for c in range(1, len(row)):
                if row[c] == 5:
                    break
                out[r][c] = 2
    return out
